    "tips": "Bạn có thể dùng 「在于」 để làm rõ lý do tại sao một sự việc lại quan trọng hoặc khó khăn, ví dụ: 「问题的关键在于时间」 (Điểm mấu chốt của vấn đề nằm ở thời gian).",
