    "explanation": "Với vai trò phó từ, 「轻易」 diễn tả việc thực hiện hành động một cách tùy tiện, thiếu cân nhắc hoặc dễ dàng từ bỏ. Nếu là tính từ, nó mang nghĩa là đơn giản, dễ dàng đạt được một điều gì đó.",
