        "hanzi": "总之，羽毛起着重要的作用。",
        "pinyin": "zǒng zhī yǔ máo qǐ zhe zhòng yào de zuò yòng",
        "meaning": "Nói tóm lại, lông vũ đóng vai trò quan trọng."
